def _join_i8_wrapper(joinf, with_indexers: bool = True):
    """
   Create the join wrapper methods.
    """

   @staticmethod  # type: ignore
   def wrapper(left, right):
       if isinstance(left, (np.ndarray, ABCIndex, ABCSeries, DatetimeLikeArrayMixin)):
           left = left.view("i8")
       if isinstance(right, (np.ndarray, ABCIndex, ABCSeries, DatetimeLikeArrayMixin)):
           right = right.view("i8")

       results = joinf(left, right)
       if with_indexers:
           # dtype should be timedelta64[ns] for TimedeltaIndex
           #  and datetime64[ns] for DatetimeIndex
           dtype = left.dtype.base

           join_index, left_indexer, right_indexer = results
           join_index = join_index.view(dtype)
           return join_index, left_indexer, right_indexer
       return results

   return wrapper


@inherit_names(
   ["inferred_freq", "_isnan", "_resolution", "resolution"],
   DatetimeLikeArrayMixin,
   cache=True,
)
@inherit_names(
   ["__iter__", "mean", "freq", "freqstr", "_ndarray_values", "asi8", "_box_values"],
   DatetimeLikeArrayMixin,
)
class DatetimeIndexOpsMixin(ExtensionIndex, ExtensionOpsMixin):
   """
   Common ops mixin to support a unified interface datetimelike Index.
   """

   _data: ExtensionArray
   freq: Optional[DateOffset]
   freqstr: Optional[str]
   _resolution: int
   _bool_ops: List[str] = []
   _field_ops: List[str] = []

   hasnans = cache_readonly(DatetimeLikeArrayMixin._hasnans.fget)  # type: ignore
   _hasnans = hasnans  # for index / array -agnostic code

    @property
   def is_all_dates(self) -> bool:
       return True

   @classmethod
   def _create_comparison_method(cls, op):
        """
       Create a comparison method that dispatches to ``cls.values``.
        """
       return make_wrapped_comparison_op(f"__{op.__name__}__")

   # ------------------------------------------------------------------------
   # Abstract data attributes

   @property
   def values(self):
       # Note: PeriodArray overrides this to return an ndarray of objects.
       return self._data._data

   def __array_wrap__(self, result, context=None):
        """
       Gets called after a ufunc.
        """
       result = lib.item_from_zerodim(result)
       if is_bool_dtype(result) or lib.is_scalar(result):
           return result

       attrs = self._get_attributes_dict()
       if not is_period_dtype(self) and attrs["freq"]:
           # no need to infer if freq is None
           attrs["freq"] = "infer"
       return Index(result, **attrs)

   # ------------------------------------------------------------------------

   def equals(self, other) -> bool:
        """
       Determines if two Index objects contain the same elements.
        """
       if self.is_(other):
           return True

       if not isinstance(other, ABCIndexClass):
           return False
       elif not isinstance(other, type(self)):
           try:
               other = type(self)(other)
           except (ValueError, TypeError, OverflowError):
               # e.g.
               #  ValueError -> cannot parse str entry, or OutOfBoundsDatetime
               #  TypeError  -> trying to convert IntervalIndex to DatetimeIndex
               #  OverflowError -> Index([very_large_timedeltas])
               return False

       if not is_dtype_equal(self.dtype, other.dtype):
           # have different timezone
           return False

       return np.array_equal(self.asi8, other.asi8)

   @Appender(_index_shared_docs["contains"] % _index_doc_kwargs)
   def __contains__(self, key):
       try:
           res = self.get_loc(key)
           return (
               is_scalar(res)
               or isinstance(res, slice)
               or (is_list_like(res) and len(res))
           )
       except (KeyError, TypeError, ValueError):
           return False

   # Try to run function on index first, and then on elements of index
   # Especially important for group-by functionality
   def map(self, mapper, na_action=None):
       try:
           result = mapper(self)

           # Try to use this result if we can
           if isinstance(result, np.ndarray):
               result = Index(result)

           if not isinstance(result, Index):
               raise TypeError("The map function must return an Index object")
           return result
       except Exception:
           return self.astype(object).map(mapper)

   def sort_values(self, return_indexer=False, ascending=True):
        """
       Return sorted copy of Index.
        """
       if return_indexer:
           _as = self.argsort()
           if not ascending:
               _as = _as[::-1]
           sorted_index = self.take(_as)
           return sorted_index, _as
       else:
           # NB: using asi8 instead of _ndarray_values matters in numpy 1.18
           #  because the treatment of NaT has been changed to put NaT last
           #  instead of first.
           sorted_values = np.sort(self.asi8)
           attribs = self._get_attributes_dict()
           freq = attribs["freq"]

           if freq is not None and not is_period_dtype(self):
               if freq.n > 0 and not ascending:
                   freq = freq * -1
               elif freq.n < 0 and ascending:
                   freq = freq * -1
           attribs["freq"] = freq

           if not ascending:
               sorted_values = sorted_values[::-1]

           return self._simple_new(sorted_values, **attribs)

   @Appender(_index_shared_docs["take"] % _index_doc_kwargs)
   def take(self, indices, axis=0, allow_fill=True, fill_value=None, **kwargs):
       nv.validate_take(tuple(), kwargs)
       indices = ensure_int64(indices)

       maybe_slice = lib.maybe_indices_to_slice(indices, len(self))
       if isinstance(maybe_slice, slice):
           return self[maybe_slice]

       return ExtensionIndex.take(
           self, indices, axis, allow_fill, fill_value, **kwargs
       )

   _can_hold_na = True

   _na_value = NaT
   """The expected NA value to use with this index."""

   def _convert_tolerance(self, tolerance, target):
       tolerance = np.asarray(to_timedelta(tolerance).to_numpy())

       if target.size != tolerance.size and tolerance.size > 1:
           raise ValueError("list-like tolerance size must match target index size")
       return tolerance

   def tolist(self) -> List:
       """
       Return a list of the underlying data.
       """
       return list(self.astype(object))

   def min(self, axis=None, skipna=True, *args, **kwargs):
       """
       Return the minimum value of the Index or minimum along
       an axis.

       See Also
        --------
       numpy.ndarray.min
       Series.min : Return the minimum value in a Series.
        """
       nv.validate_min(args, kwargs)
       nv.validate_minmax_axis(axis)

       if not len(self):
           return self._na_value

       i8 = self.asi8
       try:
           # quick check
           if len(i8) and self.is_monotonic:
               if i8[0] != iNaT:
                   return self._box_func(i8[0])

           if self.hasnans:
               if skipna:
                   min_stamp = self[~self._isnan].asi8.min()
               else:
                   return self._na_value
           else:
               min_stamp = i8.min()
           return self._box_func(min_stamp)
       except ValueError:
           return self._na_value

   def argmin(self, axis=None, skipna=True, *args, **kwargs):
        """
       Returns the indices of the minimum values along an axis.

       See `numpy.ndarray.argmin` for more information on the
       `axis` parameter.

       See Also
       --------
       numpy.ndarray.argmin
        """
       nv.validate_argmin(args, kwargs)
       nv.validate_minmax_axis(axis)

       i8 = self.asi8
       if self.hasnans:
           mask = self._isnan
           if mask.all() or not skipna:
               return -1
           i8 = i8.copy()
           i8[mask] = np.iinfo("int64").max
       return i8.argmin()

   def max(self, axis=None, skipna=True, *args, **kwargs):
        """
       Return the maximum value of the Index or maximum along
       an axis.

       See Also
       --------
       numpy.ndarray.max
       Series.max : Return the maximum value in a Series.
       """
       nv.validate_max(args, kwargs)
       nv.validate_minmax_axis(axis)

       if not len(self):
           return self._na_value

       i8 = self.asi8
       try:
           # quick check
           if len(i8) and self.is_monotonic:
               if i8[-1] != iNaT:
                   return self._box_func(i8[-1])

           if self.hasnans:
               if skipna:
                   max_stamp = self[~self._isnan].asi8.max()
               else:
                   return self._na_value
           else:
               max_stamp = i8.max()
           return self._box_func(max_stamp)
       except ValueError:
           return self._na_value

   def argmax(self, axis=None, skipna=True, *args, **kwargs):
       """
       Returns the indices of the maximum values along an axis.

       See `numpy.ndarray.argmax` for more information on the
       `axis` parameter.

       See Also
       --------
       numpy.ndarray.argmax
       """
       nv.validate_argmax(args, kwargs)
       nv.validate_minmax_axis(axis)

       i8 = self.asi8
       if self.hasnans:
           mask = self._isnan
           if mask.all() or not skipna:
               return -1
           i8 = i8.copy()
           i8[mask] = 0
       return i8.argmax()

   # --------------------------------------------------------------------
   # Rendering Methods

   def _format_with_header(self, header, na_rep="NaT", **kwargs):
       return header + list(self._format_native_types(na_rep, **kwargs))

    @property
   def _formatter_func(self):
        raise AbstractMethodError(self)

   def _format_attrs(self):
        """
       Return a list of tuples of the (attr,formatted_value).
        """
       attrs = super()._format_attrs()
       for attrib in self._attributes:
           if attrib == "freq":
               freq = self.freqstr
               if freq is not None:
                   freq = repr(freq)
               attrs.append(("freq", freq))
       return attrs

   # --------------------------------------------------------------------

   def _convert_scalar_indexer(self, key, kind=None):
        """
       We don't allow integer or float indexing on datetime-like when using
       loc.

       Parameters
       ----------
       key : label of the slice bound
       kind : {'ix', 'loc', 'getitem', 'iloc'} or None
       """

       assert kind in ["ix", "loc", "getitem", "iloc", None]

       # we don't allow integer/float indexing for loc
       # we don't allow float indexing for ix/getitem
       if is_scalar(key):
           is_int = is_integer(key)
           is_flt = is_float(key)
           if kind in ["loc"] and (is_int or is_flt):
               self._invalid_indexer("index", key)
           elif kind in ["ix", "getitem"] and is_flt:
               self._invalid_indexer("index", key)

       return super()._convert_scalar_indexer(key, kind=kind)

   __add__ = make_wrapped_arith_op("__add__")
   __radd__ = make_wrapped_arith_op("__radd__")
   __sub__ = make_wrapped_arith_op("__sub__")
   __rsub__ = make_wrapped_arith_op("__rsub__")
   __pow__ = make_wrapped_arith_op("__pow__")
   __rpow__ = make_wrapped_arith_op("__rpow__")
   __mul__ = make_wrapped_arith_op("__mul__")
   __rmul__ = make_wrapped_arith_op("__rmul__")
   __floordiv__ = make_wrapped_arith_op("__floordiv__")
   __rfloordiv__ = make_wrapped_arith_op("__rfloordiv__")
   __mod__ = make_wrapped_arith_op("__mod__")
   __rmod__ = make_wrapped_arith_op("__rmod__")
   __divmod__ = make_wrapped_arith_op("__divmod__")
   __rdivmod__ = make_wrapped_arith_op("__rdivmod__")
   __truediv__ = make_wrapped_arith_op("__truediv__")
   __rtruediv__ = make_wrapped_arith_op("__rtruediv__")

   def isin(self, values, level=None):
       """
       Compute boolean array of whether each index value is found in the
       passed set of values.

       Parameters
       ----------
       values : set or sequence of values

        Returns
        -------
       is_contained : ndarray (boolean dtype)
        """
       if level is not None:
           self._validate_index_level(level)

       if not isinstance(values, type(self)):
           try:
               values = type(self)(values)
           except ValueError:
               return self.astype(object).isin(values)

       return algorithms.isin(self.asi8, values.asi8)

   @Appender(_index_shared_docs["repeat"] % _index_doc_kwargs)
   def repeat(self, repeats, axis=None):
       nv.validate_repeat(tuple(), dict(axis=axis))
       result = type(self._data)(self.asi8.repeat(repeats), dtype=self.dtype)
       return self._shallow_copy(result)

   @Appender(_index_shared_docs["where"] % _index_doc_kwargs)
   def where(self, cond, other=None):
       values = self.view("i8")

       if is_scalar(other) and isna(other):
           other = NaT.value

        else:
           # Do type inference if necessary up front
           # e.g. we passed PeriodIndex.values and got an ndarray of Periods
           other = Index(other)

           if is_categorical_dtype(other):
               # e.g. we have a Categorical holding self.dtype
               if needs_i8_conversion(other.categories):
                   other = other._internal_get_values()

           if not is_dtype_equal(self.dtype, other.dtype):
               raise TypeError(f"Where requires matching dtype, not {other.dtype}")

           other = other.view("i8")

       result = np.where(cond, values, other).astype("i8")
       return self._shallow_copy(result)

   def _summary(self, name=None):
        """
       Return a summarized representation.

        Parameters
        ----------
       name : str
           Name to use in the summary representation.

        Returns
        -------
       str
           Summarized representation of the index.
        """
       formatter = self._formatter_func
       if len(self) > 0:
           index_summary = f", {formatter(self[0])} to {formatter(self[-1])}"
        else:
           index_summary = ""

       if name is None:
           name = type(self).__name__
       result = f"{name}: {len(self)} entries{index_summary}"
       if self.freq:
           result += f"\nFreq: {self.freqstr}"

       # display as values, not quoted
       result = result.replace("'", "")
       return result

   def _concat_same_dtype(self, to_concat, name):
       """
       Concatenate to_concat which has the same class.
       """
       attribs = self._get_attributes_dict()
       attribs["name"] = name
       # do not pass tz to set because tzlocal cannot be hashed
       if len({str(x.dtype) for x in to_concat}) != 1:
           raise ValueError("to_concat must have the same tz")

       new_data = type(self._values)._concat_same_type(to_concat).asi8

       # GH 3232: If the concat result is evenly spaced, we can retain the
       # original frequency
       is_diff_evenly_spaced = len(unique_deltas(new_data)) == 1
       if not is_period_dtype(self) and not is_diff_evenly_spaced:
           # reset freq
           attribs["freq"] = None

       return self._simple_new(new_data, **attribs)

   @Appender(_index_shared_docs["astype"])
   def astype(self, dtype, copy=True):
       if is_dtype_equal(self.dtype, dtype) and copy is False:
           # Ensure that self.astype(self.dtype) is self
           return self

       new_values = self._data.astype(dtype, copy=copy)

       # pass copy=False because any copying will be done in the
       #  _data.astype call above
       return Index(new_values, dtype=new_values.dtype, name=self.name, copy=False)

   def shift(self, periods=1, freq=None):
        """
       Shift index by desired number of time frequency increments.

       This method is for shifting the values of datetime-like indexes
       by a specified time increment a given number of times.

        Parameters
        ----------
       periods : int, default 1
           Number of periods (or increments) to shift by,
           can be positive or negative.

           .. versionchanged:: 0.24.0

       freq : pandas.DateOffset, pandas.Timedelta or string, optional
           Frequency increment to shift by.
           If None, the index is shifted by its own `freq` attribute.
           Offset aliases are valid strings, e.g., 'D', 'W', 'M' etc.

       Returns
       -------
       pandas.DatetimeIndex
           Shifted index.

        See Also
        --------
       Index.shift : Shift values of Index.
       PeriodIndex.shift : Shift values of PeriodIndex.
        """
       result = self._data._time_shift(periods, freq=freq)
       return type(self)(result, name=self.name)

   # --------------------------------------------------------------------
   # List-like Methods

   def delete(self, loc):
       new_i8s = np.delete(self.asi8, loc)

       freq = None
       if is_period_dtype(self):
           freq = self.freq
       elif is_integer(loc):
           if loc in (0, -len(self), -1, len(self) - 1):
               freq = self.freq
        else:
           if is_list_like(loc):
               loc = lib.maybe_indices_to_slice(ensure_int64(np.array(loc)), len(self))
           if isinstance(loc, slice) and loc.step in (1, None):
               if loc.start in (0, None) or loc.stop in (len(self), None):
                   freq = self.freq

       return self._shallow_copy(new_i8s, freq=freq)


class DatetimeTimedeltaMixin(DatetimeIndexOpsMixin, Int64Index):
   """
   Mixin class for methods shared by DatetimeIndex and TimedeltaIndex,
   but not PeriodIndex
   """

   # Compat for frequency inference, see GH#23789
   _is_monotonic_increasing = Index.is_monotonic_increasing
   _is_monotonic_decreasing = Index.is_monotonic_decreasing
   _is_unique = Index.is_unique

   def _set_freq(self, freq):
        """
       Set the _freq attribute on our underlying DatetimeArray.

        Parameters
        ----------
       freq : DateOffset, None, or "infer"
       """
       # GH#29843
       if freq is None:
           # Always valid
           pass
       elif len(self) == 0 and isinstance(freq, DateOffset):
           # Always valid.  In the TimedeltaIndex case, we assume this
           #  is a Tick offset.
           pass
        else:
           # As an internal method, we can ensure this assertion always holds
           assert freq == "infer"
           freq = to_offset(self.inferred_freq)

       self._data._freq = freq

   def _shallow_copy(self, values=None, **kwargs):
       if values is None:
           values = self._data
       if isinstance(values, type(self)):
           values = values._data

       attributes = self._get_attributes_dict()

       if "freq" not in kwargs and self.freq is not None:
           if isinstance(values, (DatetimeArray, TimedeltaArray)):
               if values.freq is None:
                   del attributes["freq"]

       attributes.update(kwargs)
       return self._simple_new(values, **attributes)

   # --------------------------------------------------------------------
   # Set Operation Methods

   @Appender(Index.difference.__doc__)
   def difference(self, other, sort=None):
       new_idx = super().difference(other, sort=sort)
       new_idx._set_freq(None)
       return new_idx

   def intersection(self, other, sort=False):
        """
       Specialized intersection for DatetimeIndex/TimedeltaIndex.

       May be much faster than Index.intersection

        Parameters
        ----------
       other : Same type as self or array-like
       sort : False or None, default False
           Sort the resulting index if possible.

           .. versionadded:: 0.24.0

           .. versionchanged:: 0.24.1

              Changed the default to ``False`` to match the behaviour
              from before 0.24.0.

           .. versionchanged:: 0.25.0

              The `sort` keyword is added

        Returns
        -------
       y : Index or same type as self
        """
       self._validate_sort_keyword(sort)
       self._assert_can_do_setop(other)

       if self.equals(other):
           return self._get_reconciled_name_object(other)

       if len(self) == 0:
           return self.copy()
       if len(other) == 0:
           return other.copy()

       if not isinstance(other, type(self)):
           result = Index.intersection(self, other, sort=sort)
           if isinstance(result, type(self)):
               if result.freq is None:
                   result._set_freq("infer")
           return result

       elif (
           other.freq is None
           or self.freq is None
           or other.freq != self.freq
